SELECT COUNT(1)
FROM host_vuln_result
WHERE host_id = #{hostId}
  AND tenant_id = #{tenantId}
  AND status = 1
  AND UPPER(verify_status) = UPPER(#{verifyStatus})

SELECT hvr.id AS result_id, hvr.host_id, vr.id AS rule_id, vr.product_type, vr.product_name, vr.match_type, vr.affected_version_expr AS version_expression, vr.verify_type, vr.verify_rule FROM host_vuln_result hvr INNER JOIN vuln_rule vr ON vr.id = hvr.rule_id WHERE hvr.id IN
#{id}
AND hvr.status = 1 AND hvr.rule_id IS NOT NULL AND hvr.rule_id > 0 AND UPPER(hvr.verify_status) IN ('PENDING', 'VERIFIED', 'VERIFYING', 'NOT_AFFECTED', 'REPAIR_PENDING', 'TO_FIX', 'FIXED') AND vr.enabled = 1 ORDER BY hvr.host_id ASC, hvr.id ASC

