SELECT DISTINCT expanded.id FROM host_vuln_result expanded INNER JOIN ( SELECT DISTINCT seed.host_id, seed.rule_id FROM host_vuln_result seed WHERE seed.tenant_id = #{tenantId} AND seed.id IN
#{id}
) grouped ON grouped.host_id = expanded.host_id AND grouped.rule_id = expanded.rule_id WHERE expanded.tenant_id = #{tenantId} AND expanded.status = 1 AND expanded.rule_id IS NOT NULL AND expanded.rule_id > 0 ORDER BY expanded.id DESC
